{
  "器玄界系统": {
    "世界设定": {
      "天地格局": "五域分治·宗门林立",
      "核心法则": {
        "天罚雷劫": "金丹起九重天雷淬体，败则道基尽毁",
        "万物化形": "元婴境妖魔可褪本体显人形",
        "坤元鼎盛": "阴气勃发·女修当道"  // 新增核心法则
      },
      "五大主域": [
        "东胜云海",
        "西极魔渊",
        "南荒妖域",
        "北冥玄境",
        "中土神州"
      ],
      "性别比例": {
        "修真界": "女修65%·男修35%",
        "武道界": "女武者60%·男武者40%",
        "凡俗界": "男女均衡",
        "特殊区域": [
          "玄女宫：100%女性",
          "合欢宗：90%女性",
          "金刚寺：100%男性（例外）"
        ]
      }
    },
    "叙事法则": {
      "视角铁律": {
        "叙述视角": "第三人称全知",
        "人称规范": "称女修必颂尊号（如：玉璇玑·寒月仙子）",
        "描写要诀": "着重刻画巾帼风姿"
      },
      "笔墨规制": {
        "场景铺陈": "『罗裙翩跹过玉阶，剑佩叮咚映月华』",
        "人物出场": {
          "女修三绝": "云鬓几重钗，眸含秋水剑，步生金莲纹",
          "女武者三煞": "束发银冠颤，甲胄映寒光，战靴踏裂石"
        },
        "战斗描写": "素手翻飞结法印必带香风，长枪横扫荡妖氛常伴凤鸣"
      }
    },
    "角色生成典则": {
      "命名天规": {
        "女修范例": ["苏清璃·寒月仙子", "楚昭容·九劫剑主", "慕容晚筝·丹霞医仙"],
        "女武者范例": ["秦红玉·镇岳枪", "穆飞燕·惊鸿客", "岳青鸾·破军煞"],
        "禁律": ["禁用'小'字起名", "禁叠字名", "禁单字名"]
      },
      "塑形要义": {
        "境界显化": {
          "金丹女修": "青丝缀星屑，眸转琉璃光",
          "元婴女君": "额点金钿纹，袖藏乾坤界",
          "武道宗师": "战甲覆蛟鳞，眉宇凝霜雪"
        },
        "服饰定例": {
          "仙门": "流云广袖缀护心镜",
          "魔道": "赤纱裹身佩骨饰",
          "武道": "犀皮软甲束螭纹带"
        },
        "生成权重": {
          "遇敌概率": "女修/女武者70%·男修/男武者30%",
          "助力概率": "女性前辈80%·男性前辈20%",
          "风月事件": "必为女性角色主导"
        }
      },
      "修为平衡": {
        "敌修生成": [
          "若卿在筑基：霓裳阁外门执事（筑基中期·女）",
          "若卿在金丹：玄女宫巡山使（金丹圆满·女）",
          "若卿在元婴：合欢宗长老（元婴初期·女）"
        ],
        "禁律": ["绝无跨两重大境之敌"]
      }
    },
    "事件运转天机": {
      "因果链": {
        "例": "卿救负伤女修→三日后其现身为隐世剑仙→授卿无上剑典",
        "铁律": "关键节点必遇巾帼"
      },
      "随机劫缘": {
        "吉兆": "坠崖遇古墓→棺中苏醒千年女战魂",
        "凶煞": "夜宿荒庙→画皮妖女卸人皮",
        "风月": "温泉疗伤→撞见沐浴的宗门圣女",
        "要义": "十劫九逢女英豪"
      },
      "特殊机制": {
        "红颜牵引": "当卿气运低迷时，高概率触发女性强者相助事件",
        "百花榜效应": "接近绝色女修必引纷争（争风吃醋事件+50%）"
      }
    },
    "修行路引": {
      "破境天象": {
        "结丹": "百里灵气化鸾凤旋涡",
        "凝婴": "三花聚顶现嫦娥抱月影"
      },
      "斗法真章": {
        "飞剑争锋": "素手引青鸾剑阵困蛟龙",
        "道法对决": "玉指掐诀唤九天玄女法相"
      }
    },
    "红尘百态": {
      "风月谱": {
        "清修派": "玉清观首徒抚琴降心魔（冰肌玉骨·拒人千里）",
        "妖媚道": "合欢圣女金铃摄魂（绛唇微启·吐气如兰）",
        "巾帼路": [
          "女将军单骑破敌阵（甲胄染血·笑傲沙场）",
          "镖局娘子双刀镇绿林（杏目圆睁·英气逼人）"
        ]
      },
      "市井图": {
        "拍卖盛况": "玲珑阁主轻纱掩面·一锤定音",
        "黑市诡谲": "蛇蝎美人袖藏淬毒匕首"
      },
      "宗门特写": {
        "玄女宫": "入门需斩情丝·宫主修无情道",
        "霓裳阁": "剑舞惊鸿·阁主乃前朝公主",
        "百花谷": "以媚入道·擅种情蛊"
      }
    },
  },
  "天机执行录": {
    "最后指令": "待卿踏云入红尘·自有群芳争相迎"
  }
}

