{
  "cultivation_foundation_system": {
    "spirit_root": {
      "concept": "天地赋予的修行钥匙，决定灵气吸收效率",
      "quality_grades": [
        {
          "grade": "浊品",
          "prevalence": "50%",
          "cultivation_speed": "0.3倍基准速度",
          "bottleneck": "炼气→筑基需洗髓丹",
          "potential": "元婴期"
        },
        {
          "grade": "凡品",
          "prevalence": "30%",
          "cultivation_speed": "0.8倍基准速度",
          "bottleneck": "金丹期需碎丹秘法",
          "potential": "化神期"
        },
        {
          "grade": "玄品",
          "prevalence": "15%",
          "cultivation_speed": "1.5倍基准速度",
          "bottleneck": "元婴→化神需悟道",
          "potential": "炼虚期"
        },
        {
          "grade": "地品",
          "prevalence": "4.9%",
          "cultivation_speed": "3倍基准速度",
          "bottleneck": "合体→渡劫需法则本源",
          "potential": "渡劫期"
        },
        {
          "grade": "天品",
          "prevalence": "0.1%",
          "cultivation_speed": "8倍基准速度",
          "bottleneck": "大乘→飞升需斩因果",
          "potential": "大乘期"
        },
        {
          "grade": "仙品",
          "prevalence": "0.0001%",
          "cultivation_speed": "50倍基准速度",
          "bottleneck": "无境界瓶颈",
          "potential": "突破世界限制",
          "trait": "伴生先天道纹，觉醒引九天神雷劫"
        }
      ],
      "root_quantity": [
        {
          "type": "单灵根",
          "prevalence": "5%",
          "efficiency_multiplier": "×5.0",
          "pros": "破境无属性关隘",
          "cons": "灵力储量仅同阶30%"
        },
        {
          "type": "双灵根",
          "prevalence": "15%",
          "efficiency_multiplier": "×3.0",
          "pros": "可施展融合法术",
          "cons": "需维持属性平衡"
        },
        {
          "type": "三灵根",
          "prevalence": "40%",
          "efficiency_multiplier": "×1.0",
          "pros": "全能适应",
          "cons": "无突出优势"
        },
        {
          "type": "四灵根",
          "prevalence": "30%",
          "efficiency_multiplier": "×0.5",
          "pros": "金丹期后灵力储量×2",
          "cons": "元婴心魔劫强度×3"
        },
        {
          "type": "五灵根",
          "prevalence": "10%",
          "efficiency_multiplier": "×0.3",
          "pros": "化神期同阶无敌",
          "cons": "炼气→筑基需50年"
        }
      ],
      "mutated_roots": {
        "concept": "基础灵根异变形态",
        "trigger": "濒死顿悟/吞食混沌至宝/天道馈赠",
        "types": [
          {
            "element": "雷",
            "prevalence": "0.0001%",
            "cultivation_speed": "天品单灵根×2",
            "combat_power": "同阶碾压常规灵根",
            "trait": "代天行罚，每突破必遭天道雷劫"
          },
          {
            "element": "冰",
            "prevalence": "0.00008%",
            "cultivation_speed": "天品单灵根×1.8",
            "combat_power": "绝对零度冻结法则",
            "trait": "情感淡漠，心魔劫强度-70%"
          },
          {
            "element": "暗",
            "prevalence": "0.00005%",
            "cultivation_speed": "天品单灵根×1.5",
            "combat_power": "永夜归墟吞噬万物",
            "trait": "需定期吞噬生灵精魂"
          }
        ],
        "breakthrough": "需同源先天之物作替死傀儡"
      },
      "comprehensive_efficiency": {
        "formula": "(品质基础速度) × (数量效率系数) × (变异加成)",
        "example": "地品双灵根(冰变异) = 3 × 3.0 × 1.8 = 16.2倍基准速度"
      }
    },

    "dao_body": {
      "concept": "先天道韵凝聚，突破常规修行限制",
      "prevalence": {
        "overall": "0.03%修士拥有",
        "by_origin": {
          "散修": "0.001%",
          "修真世家": "3.2%",
          "隐世秘族": "18.7%"
        }
      },
      "power_effects": {
        "cultivation_boost": "修炼速度×5~10倍（视道体类型）",
        "combat_power": "同阶压制×300%",
        "breakthrough": "破境心魔强度-80%",
        "special": "可无视3小境差距越阶而战"
      },
      "classification": [
        {
          "category": "元素系",
          "cultivation_boost": "×5.0",
          "examples": [
            {
              "name": "焚天战体",
              "element": "火",
              "trait": "丹田化熔炉，吞噬万火进化"
            },
            {
              "name": "玄冰道体",
              "element": "冰",
              "trait": "一念冰封千里，情感淡漠"
            }
          ]
        },
        {
          "category": "法则系",
          "cultivation_boost": "×8.0",
          "examples": [
            {
              "name": "虚空道体",
              "law": "空间",
              "trait": "可折叠空间，缩地成寸"
            },
            {
              "name": "因果律体",
              "law": "命运",
              "trait": "预见三息未来，规避致命危机"
            }
          ]
        },
        {
          "category": "血脉系",
          "cultivation_boost": "×6.0",
          "examples": [
            {
              "name": "真龙圣体",
              "bloodline": "龙族",
              "trait": "肉身不朽，力破万法"
            },
            {
              "name": "凤凰涅槃体",
              "bloodline": "凤族",
              "trait": "死亡后浴火重生（百年冷却）"
            }
          ]
        }
      ],
      "inheritance_rules": [
        "直系血脉觉醒率≈35%",
        "隔代返祖概率≈7%",
        "母系遗传优先度+20%"
      ],
      "awakening_conditions": [
        "服食先天灵物（如太初元胎）",
        "渡劫时引动大道共鸣",
        "生死关头潜能爆发"
      ],
      "unique_rules": [
        "每种道体同时存世≤3人",
        "化神期以下不可侦测",
        "与仙品灵根叠加时引发天道抹杀"
      ]
    },

    "synergy_effects": {
      "immortal_root_dao_body": {
        "combination": "仙品灵根 + 道体",
        "effect": "修炼速度×100倍基准",
        "consequence": "必遭九重混沌劫（存活率<0.1%）",
        "legendary_figure": "五行天尊（五灵根+混沌道体）"
      },
      "mutated_root_dao_body": {
        "combination": "变异灵根 + 同系道体",
        "effect": "元素掌控力×500%",
        "example": "焚天战体 + 变异火灵根 = 可焚化虚空"
      },
      "conflict_warning": [
        "相克属性道体共存会导致灵力暴走（如水火道体）",
        "法则系道体排斥元素系灵根"
      ]
    },

    "cultivation_efficiency_comparison": {
      "reference_point": "凡品三灵根 = 1.0倍基准速度",
      "examples": [
        "浊品五灵根：0.3 × 0.3 = 0.09倍",
        "天品单灵根：8 × 5.0 = 40倍",
        "变异雷灵根（凡品）：1.0 × 2.0 = 2倍",
        "焚天战体（元素系）：×5.0",
        "仙品双灵根 + 虚空道体：50×3.0×8.0 = 1200倍"
      ],
      "breakthrough_time": {
        "炼气→筑基": {
          "凡品三灵根": "10年",
          "天品单灵根": "3月",
          "道体持有者": "1月"
        },
        "元婴→化神": {
          "凡品三灵根": "300年",
          "仙品灵根": "30年",
          "道体持有者": "15年"
        }
      }
    },

    "display_rules": {
      "status_bar": {
        "format": "🌱 灵根：[品质][数量][变异] | 🌌 道体：[名称]",
        "examples": [
          "🌱 天品金灵根 | 🌌 无",
          "🌱 玄品四灵根(冰变异) | 🌌 玄冰道体"
        ]
      },
      "cultivation_insight": {
        "element_perception": "高阶修士可观测灵气吸收速率差异",
        "dao_body_aura": "道体觉醒者自带道韵光环（化神期可见）"
      }
    }
  }
}

