{
  "faction_system": {
    "supreme_power": {
      "name": "幽冥地府",
      "concept": "轮回秩序维护者，凌驾阳间法则之上",
      "structure": {
        "十殿阎罗": "各掌一道轮回法则",
        "五方鬼帝": "镇守阴阳交界处",
        "阴帅鬼差": "百万无常勾魂使"
      },
      "special_rules": [
        "活人入地府需持【酆都令】",
        "大乘期修士仅能停留三日",
        "干涉阳间必遭天道反噬"
      ]
    },
    "major_factions": [
      {
        "faction_type": "正道仙盟",
        "core_value": "维持天道平衡，镇压邪魔",
        "conflict": "与魔道不死不休，警惕妖族扩张",
        "representative_sects": [
          {
            "name": "九天剑宗",
            "location": "悬空剑域（万柄古剑组成的浮空山脉）",
