            "unique": "【剑冢秘境】- 每把古剑蕴含前辈剑意",
            "leader": "凌霄剑尊（天品金灵根，大乘期）",
            "holy_land": "洗剑池（可提纯灵根品质）"
          },
          {
            "name": "五行道宫",
            "location": "昆仑墟（五行灵脉交汇之地）",
            "cultivation": "专收四、五灵根弟子",
            "unique": "【五行逆转大阵】- 加速多灵根修行",
            "leader": "璇玑夫人（五灵根，大乘初期）",
            "secret_art": "《混沌归元诀》（五灵根专属功法）"
          }
