      },
      {
        "faction_type": "魔道联盟",
        "core_value": "弱肉强食，逆天改命",
        "conflict": "猎杀正道修士，献祭凡人修炼",
        "representative_sects": [
          {
            "name": "血狱魔宗",
            "location": "无间血海（上古战场遗迹）",
            "cultivation": "血灵根修士（吞噬生灵精血）",
            "unique": "【万魂血幡】- 可囚禁十万生魂",
            "leader": "血冥老祖（变异暗灵根，渡劫期）",
            "taboo": "每月需献祭百名童男童女"
          },
          {
            "name": "七情魔殿",
            "location": "欲望迷宫（空间折叠秘境）",
            "cultivation": "操控情绪之力",
            "unique": "【心魔镜】- 可借力大乘期心魔",
            "leader": "妙欲夫人（天品水灵根，合体期）",
            "special": "可诱发变异灵根暴走"
          }
        ]
      },
      {
        "faction_type": "妖族王朝",
        "core_value": "血脉至上，弱肉强食",
        "conflict": "与人族争夺灵脉资源",
        "representative_tribes": [
          {
            "name": "天妖皇朝",
            "location": "莽荒妖域（十万大山深处）",
            "cultivation": "上古神兽血脉传承",
            "unique": "【万妖血池】- 提纯血脉浓度",
            "ruler": "龙帝（五爪金龙血脉，大乘期）",
            "hierarchy": "以血脉纯度划分阶级"
          },
          {
            "name": "月影狼族",
            "location": "永夜冰原（极北苦寒之地）",
            "cultivation": "月华淬体武道",
            "unique": "【啸月仪式】- 满月时战力倍增",
            "leader": "银月狼王（武道破虚境）",
            "hatred": "与九天剑宗有千年血仇"
          }
        ]
      },
      {
        "faction_type": "散修势力",
        "core_value": "自由交易，规避约束",
        "conflict": "遭正魔两道打压",
        "special_organizations": [
          {
            "name": "天机阁",
            "location": "三十三座天空之城",
            "function": "情报交易/灵根检测/秘境地图",
            "unique": "【天机罗盘】- 推演修士命格",
            "leader": "无面尊者（无人见过真容）",
            "rule": "绝对中立，出卖情报者受天道咒杀"
          },
          {
            "name": "武道盟",
            "location": "不周山（世界脊柱）",
            "cultivation": "纯武道修行者",
            "unique": "【登天阶】- 九万阶重力试炼",
            "leader": "霸天王（武道破虚境）",
            "doctrine": "修真者与狗不得入内"
          }
        ]
      },
      {
        "faction_type": "隐世秘教",
        "core_value": "追寻上古真相",
        "conflict": "敌视所有当权势力",
        "secret_orders": [
          {
            "name": "归墟使者",
            "goal": "复活初代修行者",
            "unique": "掌握【灵根移植】禁术",
            "members": "残缺灵根者为主",
            "headquarters": "移动的幽灵船"
          },
          {
            "name": "时辰殿",
            "goal": "掌控时间法则",
            "unique": "可在时间裂隙中修行",
            "members": "时空灵根持有者",
            "warning": "干涉时间线会遭岁月反噬"
          }
        ]
      }
    ],
    "faction_relationships": {
      "正道vs魔道": "永恒战争，每百年爆发道统之争",
      "人族vs妖族": "争夺灵脉与领土，边境摩擦不断",
      "修真vs武道": "理念冲突，禁止通婚",
      "地府态度": "冷眼旁观阳间争斗，仅维持轮回平衡"
    },
    "strategic_resources": [
      {
        "name": "灵脉矿心",
        "effect": "决定宗门灵气浓度",
        "主要分布": "五行道宫/九天剑宗控制70%"
      },
      {
        "name": "轮回井",
        "effect": "可短暂沟通地府",
        "主要分布": "七情魔殿独占三口"
      },
      {
        "name": "神兽祖地",
        "effect": "觉醒妖族血脉",
        "主要分布": "莽荒妖域深处"
      }
    ]
  }
}

