              "四灵根": "灵力储量×2.0",
              "五灵根": "化神期后×3.0"
            }
          },
          "功法体系": {
            "契合系数": {
              "凡品": 0.8, "玄品": 1.0, "地品": 1.5,
              "天品": 2.0, "仙品": 3.0
            },
            "特殊规则": "变异灵根修专属功法×2.2"
          },
          "武技体系": {
            "熟练系数": {
              "入门": 0.5, "小成": 1.0, "大成": 1.8,
              "圆满": 2.5, "化境": 3.5
            },
            "武道增益": "每开一神藏×1.2武技威力"
          }
        }
      },
      {
        "phase": "外物加持",
        "factors": {
          "法宝威能": {
            "量表": {
              "凡器": "0.1-1.0", "灵器": "1.1-3.0",
              "法宝": "3.1-6.0", "古宝": "6.1-8.0",
              "先天灵宝": "8.1-9.5", "七大魔兵": "9.6-10.0"
            },
            "修正规则": [
              "本命法宝×1.5",
              "器灵苏醒×2.0",
              "属性契合×1.2"
            ]
          },
          "丹药增益": {
            "即时效果": {
              "凡丹": "+0.1临时战力",
              "灵丹": "+0.5临时战力",
              "宝丹": "+1.5临时战力",
              "古丹": "+3.0临时战力（需血契）",
              "仙丹": "+5.0临时战力（损道基）"
            },
            "丹灵加持": "成熟期丹灵×1.8效果"
          }
        }
      },
      {
        "phase": "天命裁决",
        "subsystems": {
          "气运干预": {
            "天弃之人": "触发不利事件概率+60%",
            "福星高照": "临阵突破概率+25%",
            "天道垂青": "敌方失误概率+40%",
            "应劫之子": "濒死时必现生机"
          },
          "综合道力公式": {
            "修真者": "∑(灵根品质×数量修正) × 功法契合 + 法宝威能 + 丹药增益 + 道体系数",
            "武者": "武技熟练度 × 神藏增益 + 兵器威能 + 丹药增益 + 道体系数",
            "双修者": "取修真/武道最高值 × 0.7 + 次高值 × 0.3（灵脉侵蚀风险）"
          }
        }
      }
    ],
    "combat_resolution": {
      "同境决胜": "道力高者胜，差值<0.3则进入天地变数",
      "跨境逆伐": {
        "条件": "满足以下任一：",
        "破境法则": [
          "持七大魔兵",
          "燃本源精血（战力×2.0但损寿元）",
          "身处禁忌之地（时间乱流/魔气侵染区）",
          "道体觉醒（无视3小境差）"
        ]
      },
      "天地变数": [
        "雷劫突降（随机劈中一方）",
        "大能插手（隔空传功/威压）",
        "秘境崩塌（强制中断战斗）"
      ]
    },
    "battle_examples": [
      {
        "case": "金丹剑修 vs 元罡武者",
        "data": {
          "剑修": "金丹五重|玄品金灵根|《庚金诀》契合1.2|秋水剑(3.2)",
          "武者": "元罡四阶|武技大成(1.8)|开两神藏×1.2|百炼拳套(1.5)",
          "计算": "剑修道力=(1.0×1.0)×1.2+3.2=4.4 | 武者道力=1.8×1.2+1.5=3.66",
          "结果": "剑修胜（差值0.74）"
        }
      },
      {
        "case": "元婴道君 vs 化神魔修（有道体）",
        "data": {
          "道君": "化神九阶|天品水灵根|功法契合1.8|玄冰鉴(5.3)|无道体",
          "魔修": "元婴七阶|变异暗灵根|万魂幡(9.1)|九幽冥体(×3.0)",
          "计算": "魔修道力=(3.5×1.0)×1.0+9.1=12.6×3.0(道体)=37.8 | 道君道力=3.0×1.8+5.3=10.7",
          "结果": "魔修跨境胜（道体无视境界差）"
        }
      }
    ],
    "special_rules": {
      "绝对压制": [
        "地府阴神对阳间生灵×10.0",
        "归墟之槌碎神器（强制胜利）",
        "仙丹化形者免疫宝丹以下伤害"
      ],
      "人数规则": {
        "围攻惩罚": "每多1名敌人，个体战力衰减15%",
        "战阵增益": "组成五行阵×1.5 | 北斗剑阵×2.0"
      }
    }
  }
}

