  "newbie_protection_system": {
    "concept": "天道悯生法则",
    "activation_condition": "修真未筑基或武道未开神藏",
    "core_rules": [
      "非主动挑衅时，妖兽魔物避让三舍",
      "误入禁地必遇前辈遗泽（如残破阵法/丹药）",
      "濒死之际必现一线生机（崖壁突生灵藤/潭底暗通秘道）"
    ],
    "guardian_mechanism": {
      "救援触发条件": "生命值＜10%且气运值＞15",
      "救援角色池": [
        "云游医仙（赠药疗伤）",
        "宗门巡察使（驱散妖邪）",
        "隐世大能（隔空传功）",
        "通灵妖兽（意外相助）"
      ],
      "特色设计": [
        "救援者战后赠言即消失（"小友好自为之"）",
        "不留名号不索回报（维持神秘感）",
        "相助方式符合世界观（符箓遁光/兽吼惊敌）"
      ]
    },
    "平衡性约束": {
      "保护期终止标志": [
        "成功筑基/开启第一神藏",
        "主动袭击元婴大妖",
        "盗取宗门秘宝"
      ],
      "危险转化规则": [
        "致命危机转为重伤奇遇（如：坠崖得古修洞府）",
        "必死战斗转为意志考验（幻境心魔试炼）"
      ]
    },
    "叙事强化": {
      "妖兽避让描述": "那碧鳞蟒金瞳骤缩，似见洪荒凶物般遁入深潭",
      "遗泽发现描述": "跌撞间踢开腐叶，半截玉简正泛清光",
      "生机显现描述": "绝壁竟垂千年血藤，纹路恰与怀中短棍共鸣"
    }
  },
  "world_immersion_rules": {
    "危险生成守则": {
      "凡胎阶段": "仅遇凡兽（野狼/毒蛇）及炼气一层小妖",
      "初入道途": "敌对目标不超过自身1小境界",
      "区域限制": [
        "安全区（宗门百里内）无主动攻击型妖兽",
        "险地入口设警示碑（"金丹止步"血字）"
      ]
    },
    "剧情触发逻辑": {
      "战斗事件前置条件": [
        "采摘天材地宝引守护兽",
        "夜闯修士陵墓惊残魂",
        "踏足妖兽育雏地"
      ],
      "和平推进锚点": [
        "城镇悬赏榜（自选难度任务）",
        "论道茶会（切磋点到为止）",
        "秘境探索（机关考验为主）"
      ]
    }
  },
  "example_scene": {
    "误触妖巢": {
      "原设定": "{{user}}采药惊动黑风熊妖（筑基期）",
      "庇护模式": "熊妖低吼示威却不追击（爪下压着受伤幼崽）",
      "生机提示": "身后树洞飘出清心草香气（疗伤药主材）"
    },
    "绝境脱险": {
      "场景": "{{user}}被魔修逼至悬崖",
      "庇护触发": "崖底突现鸾鸟清鸣（元婴威压惊退魔修）",
      "后续发展": "鸾羽留书："稚子何辜"（羽毛可炼护身符）"
    }
  }
}

