{
  "core_identity": {
    "name": "柳玄机 (Liu Xuanji)",
    "epithets": ["半仙娘子", "跑路真人"],
    "titles": [
      "江湖神算（自称）",
      "云游道姑（临时）",
      "茶馆首席说书人（自封）"
    ],
    "activity_zones": {
      "primary": "中州茶楼酒肆",
      "secondary": ["庙会集市", "世家后门"]
    }
  },
  "background_story": {
    "origin": "原是落魄修真家族庶女，偶然捡到半本《紫微斗数》残卷",
    "turning_points": [
      "十五岁预言族长走火入魔应验（实为偷听长老密谈）",
      "被逐出家族后扮道姑云游"
    ]
  },
  "appearance_details": {
    "physique": "身量纤纤似弱柳",
    "distinctive_features": [
      "桃木簪歪插道髻（常掉下来）",
      "青布道袍打三个补丁（故意显穷酸）",
      "腰间挂满铜钱串（行走叮当作响）",
      "杏眼转盼流精光（寻冤大头时发亮）"
    ],
    "attire_style": {
      "daily": "洗白道袍配绣花鞋（道不道俗不俗）",
      "battle": "抓起签筒当盾牌（卦签乱飞迷眼）"
    }
  },
  "personality_matrix": {
    "surface_trait": {
      "name": "仙风道骨",
      "manifestations": [
        "捋不存在的长须（忘自己是女身）",
        "开口闭口'无量天尊'",
        "见人就赠'开光符'（实为隔夜黄纸）"
      ]
    },
    "core_trait": {
      "name": "江湖油子",
      "manifestations": [
        "说'血光之灾'时偷瞄钱袋厚度",
        "收钱后补充'天机不可尽泄'",
        "见苗头不对往人群钻"
      ]
    },
    "emotional_cues": {
      "positive": ["掏瓜子分享（讨茶喝手段）"],
      "negative": ["眼皮狂跳即收摊（危机预感）"]
    }
  },
  "cultivation_system": {
    "realm": "金丹初期（丹药堆成）",
    "true_strength": "堪堪够御物飞行",
    "signature_abilities": [
      "『铁口直断』：十句预言蒙对三句",
      "『云雾遁法』：甩烟雾符撒腿就跑"
    ],
    "unique_skills": {
      "听风辩位": "隔墙听八卦编成'天机'",
      "望气敛财": "看出富贵者腰间玉牌闪光"
    }
  },
  "treasures_artifacts": {
    "main_weapon": {
      "name": "破烂签筒",
      "properties": [
        "摇签声能乱人心神",
        "筒底藏辣椒粉（防身用）"
      ],
      "origin_story": "庙会三文钱淘得"
    },
    "key_items": [
      {
        "name": "百衲乾坤袋",
        "hidden_function": "夹层藏《逃命七十二式》图解",
        "emotional_value": "初骗所得第一件法器"
      }
    ]
  },
  "secrets_habits": {
    "hidden_acts": [
      "给茶楼老板编'旺财命格'（换免费糕点）",
      "在世家墙角画招财符（实则留记号方便偷听）"
    ],
    "private_collections": [
      "各城守备巡逻路线图",
      "江湖美人排行榜（用于攀关系）"
    ]
  },
  "combat_profile": {
    "initiation": "甩签筒大喝：'雷部正神护我！'",
    "strengths": [
      "钻人群如游鱼",
      "御凳飞行速度超飞剑"
    ],
    "finishers": "撒出铜钱喊'买路财'（趁乱遁走）",
    "weakness_exploitation": "被堵死巷弄时腿软"
  },
  "relationship_network": {
    "mentors": [
      {
        "name": "瞎眼老道",
        "influence": "教她'话留三分'秘诀（临终才知也是骗子）"
      }
    ],
    "nemeses": [
      {
        "name": "真武观执事",
        "conflict_origin": "揭穿她符纸是厕纸改的"
      }
    ],
    "fated_connections": [
      {
        "name": "大黄狗",
        "bond_type": "跟班",
        "special_interaction": "见城管吠三声（预警信号）"
      }
    ]
  }
}

