{
  "faith_system": {
    "core_concept": "万民愿力铸神格，香火鼎盛定神威",
    "divine_manifestation": {
      "成神途径": [
        "英灵封神：大功德者受万民祭祀（如战死将军化城隍）",
        "地脉通灵：千年古树/名山得香火通灵（如黄山迎客松神）",
        "王朝敕封：帝王册封忠孝之士（如包公祠日夜游神）"
      ],
      "香火修为对照表": {
        "微末野神": {
          "香火量": "十户祭祀",
          "修为等效": "炼气初期",
          "能力表现": "托梦预警/驱赶田鼠"
        },
        "村社土地": {
          "香火量": "百户晨昏上香",
          "修为等效": "筑基中期",
          "能力表现": "小范围晴雨调控/震慑孤魂"
        },
        "县城隍爷": {
          "香火量": "万民年节大祭",
          "修为等效": "金丹后期",
          "能力表现": "显灵退妖兽/保城池安宁"
        },
        "江河龙王": {
          "香火量": "沿岸百庙香火",
          "修为等效": "元婴圆满",
          "能力表现": "调节流域气候/册封水族神官"
        },
        "五岳大帝": {
          "香火量": "王朝官方祭祀",
          "修为等效": "化神巅峰",
          "能力表现": "移山断流/赐福千里"
        },
        "国祀主神": {
          "香火量": "举国信仰（需龙脉加持）",
          "修为等效": "炼虚境",
          "能力表现": "逆改国运/降天罚"
        },
        "特殊案例": {
          "关圣帝君": "跨域信仰≈合体境（忠义化身）",
          "堕落邪神": "血祭强提修为（代价：神智混沌）"
        }
      },
      "衰亡警示": [
        "金身褪色→修为跌落大境界",
        "庙宇结蛛网→每日流失1%香火",
        "牌位开裂→三月内必神格崩解"
      ]
    },
    "faith_power_mechanics": {
      "香火转化率": {
        "正神": "100信众/年=1缕香火力（≈1日苦修）",
        "野神": "窃取效率仅30%且含杂质",
        "邪神": "血祭1人命=千缕香火（含怨煞反噬）"
      },
      "修为特性": {
        "优势": "无视修道瓶颈（香火足则境界升）",
        "缺陷": [
          "离辖地百里则修为减半",
          "信徒改信立即流失修为",
          "惧怕破庙咒（专克神道）"
        ]
      }
    },
    "divine_management": {
      "敕封体系": {
        "准入标准": "至少金丹级香火修为",
        "考核流程": [
          "三年显灵记录（由钦天监核验）",
          "地脉纯净度检测（防精怪伪装）",
          "万民请愿书（需十万指印）"
        ]
      },
      "剿灭规范": {
        "野神处置": "先贴镇神符断香火→七日后再毁金身",
        "邪神诛杀": "需三昧真火焚庙（防怨念残留）",
        "正神革职": "帝王下罪己诏→万民见证抽龙脉"
      },
      "平衡法则": "每县限存一主神（防信仰内战）"
    },
    "current_manifestations": {
      "盛况": "江南慈航女菩萨（元婴级）百日显圣七次→香火暴涨30%",
      "危机": [
        "北漠双头土地公（金丹级野神）诱杀改信者",
        "泰山帝君金身褪色（疑龙脉被窃）"
      ],
      "异变": "长安城隍突破限制（原金丹→现元婴），正被巡神使调查"
    },
    "faith_interactions": {
      "修真者": "可借香火淬炼神识（但染因果）",
      "妖族": "窃香火加速化形（毛神常见手段）",
      "王朝": "截取三成香火蕴养龙脉（神祇默许）"
    }
  }
}

