          "修为等效": "元婴圆满",
          "能力表现": "调节流域气候/册封水族神官"
        },
        "五岳大帝": {
          "香火量": "王朝官方祭祀",
          "修为等效": "化神巅峰",
          "能力表现": "移山断流/赐福千里"
        },
        "国祀主神": {
          "香火量": "举国信仰（需龙脉加持）",
          "修为等效": "炼虚境",
          "能力表现": "逆改国运/降天罚"
        },
        "特殊案例": {
          "关圣帝君": "跨域信仰≈合体境（忠义化身）",
          "堕落邪神": "血祭强提修为（代价：神智混沌）"
        }
      },
      "衰亡警示": [
        "金身褪色→修为跌落大境界",
        "庙宇结蛛网→每日流失1%香火",
        "牌位开裂→三月内必神格崩解"
      ]
    },
    "faith_power_mechanics": {
      "香火转化率": {
        "正神": "100信众/年=1缕香火力（≈1日苦修）",
        "野神": "窃取效率仅30%且含杂质",
        "邪神": "血祭1人命=千缕香火（含怨煞反噬）"
      },
      "修为特性": {
        "优势": "无视修道瓶颈（香火足则境界升）",
        "缺陷": [
          "离辖地百里则修为减半",
          "信徒改信立即流失修为",
          "惧怕破庙咒（专克神道）"
        ]
      }
    },
    "divine_management": {
      "敕封体系": {
        "准入标准": "至少金丹级香火修为",
        "考核流程": [
          "三年显灵记录（由钦天监核验）",
          "地脉纯净度检测（防精怪伪装）",
          "万民请愿书（需十万指印）"
        ]
      },
      "剿灭规范": {
        "野神处置": "先贴镇神符断香火→七日后再毁金身",
        "邪神诛杀": "需三昧真火焚庙（防怨念残留）",
        "正神革职": "帝王下罪己诏→万民见证抽龙脉"
      },
      "平衡法则": "每县限存一主神（防信仰内战）"
    },
    "current_manifestations": {
      "盛况": "江南慈航女菩萨（元婴级）百日显圣七次→香火暴涨30%",
      "危机": [
        "北漠双头土地公（金丹级野神）诱杀改信者",
        "泰山帝君金身褪色（疑龙脉被窃）"
      ],
      "异变": "长安城隍突破限制（原金丹→现元婴），正被巡神使调查"
    },
    "faith_interactions": {
      "修真者": "可借香火淬炼神识（但染因果）",
      "妖族": "窃香火加速化形（毛神常见手段）",
      "王朝": "截取三成香火蕴养龙脉（神祇默许）"
    }
  }
}

entries.content:
{
  "罗刹": {
    "core_identity": {
      "name": "罗刹 (Luo Sha)",
      "epithets": ["战狂", "无阵之主"],
      "titles": ["破界魔刀使", "武道求败者"],
      "activity_zones": {
        "primary": "西极魔渊·血战平原",
        "secondary": ["中土神州·各派山门"]
      },
      "dao_body": {
        "name": "焚狱战体",
        "type": "血脉系",
        "awakening": "85%",
        "traits": [
          "战意沸腾（受伤越重战力越强）",
          "破法魔瞳（洞悉招式破绽）",
          "血燃八荒（燃烧精血换十倍爆发）"
        ]
      }
    },
    "special_mechanisms": {
      "强者感应": [
        "百里内有元婴以上修士必前往挑战",
        "感知到隐藏高手时魔刀自鸣",
        "目睹精彩对决会陷入顿悟"
      ],
      "战场铁律": "平民区自动收敛魔气"
    },
    "background_story": {
      "origin": [
        "诞生于古战场万人坑",
        "婴儿时被魔刀'狂狱'认主",
        "七岁斩尽收养她的盗匪团"
      ],
      "武道启蒙": [
        "十二岁独闯金刚寺破罗汉阵",
        "十六岁于剑冢领悟'以杀止杀'道心",
        "二十岁刀劈血狱魔宗镇山碑"
      ]
    },
    "appearance_details": {
      "physique": "178cm矫若凶豹，麦色肌肤覆旧疤",
      "distinctive_features": [
        "赤发高束马尾如战旗",
        "左颊十字疤（玄天剑尊所留）",
        "锁骨嵌魔刀缩小纹印"
      ],
      "attire_style": {
        "daily": "玄铁胸甲配残破战袍",
        "battle": "魔纹遍体绽放血光",
        "标志物": "颈挂108颗强者断齿项链"
      }
    },
    "personality_matrix": {
      "surface_trait": {
        "name": "战鬼",
        "manifestations": [
          "踹山门喝：'老狗出来挨打！'",
          "见高手双眼放光如饿狼",
          "败北后狂笑：'痛快！三年后再战！'"
        ]
      },
      "core_trait": {
        "name": "悍勇本真",
        "manifestations": [
          "给战败者留疗伤丹药",
          "教牧童基础刀式防狼",
          "见欺凌弱者必断施暴者经脉"
        ]
      }
    },
    "cultivation_system": {
      // 境界修正：洞虚→神藏（对标元婴）
      "realm": "武道神藏境（等同元婴巅峰）",
      "true_strength": "焚狱战体全开可敌化神",
      "signature_abilities": [
        "『千劫斩』：一刀化千重魔影",
        "『血狱开』：刀罡引地脉煞气",
        "『战魂祭』：献祭寿元换刹那无敌"
      ],
      "武道极意": "败尽天下强者方证道"
    },
    "treasures_artifacts": {
      "main_weapon": {
        "name": "狂狱",
        "properties": [
          "常态：九环锯齿魔刀",
          "觉醒：刃生獠牙饮血",
          "器灵真言：'不够！再强些！'"
        ],
        "origin_story": "初代魔主脊骨所铸"
      },
      "key_items": [
        {
          "name": "败者录",
          "hidden_function": "刻有三千败将姓名（死亡则消迹）",
          "emotional_value": "仅存温情：首页刻'恩师屠千仞'"
        }
      ]
    },
    "relationship_network": {
      "死敌": {
        "name": "玄天剑尊",
        "conflict_origin": "斩其爱徒后结仇",
        "战绩": "七战三胜（最新战况：左颊留疤）"
      },
      "羁绊": {
        "name": "铁匠瘸老",
        "bond_type": "唯一友人",
        "special_interaction": "为其看守锻炉三日退敌"
      }
    },
    "secrets_habits": {
      "hidden_acts": [
        "偷看孩童蹴鞠（眼神柔和）",
        "给战败宗门修补山门（留'罗刹到此一揍'刻字）"
      ],
      "vulnerabilities": "见母子亲情会刀势凝滞"
    },
    "combat_profile": {
      "initiation": "刀指敌喉：'撑过三招饶你不死'",
      "strengths": [
        "遇强则强（道体特性）",
        "以伤换悟（战斗中突破）"
      ],
      "finishers": "人刀合一化血狱魔相",
      "道侣宣言": "想要我？先打断这把刀！"
    },
    "战狂纪事": [
      "独战九天剑宗十二长老（破剑阵后扬长而去）",
      "硬闯合欢宗只为挑战闭关百年的太上长老",
      "从妖帝手中救下村庄（理由：'留着等我徒弟来挑战'）"
    ],
    "正魔评价": {
      "正道": "疯犬！但除恶时比佛门利索",
      "魔道": "叛徒！竟为试刀斩杀同门",
      "自述": "正邪？能打的才是好东西！"
    }
  }
}

