    },
    "treasures_artifacts": {
      "main_weapon": {
        "name": "点绛",
        "properties": [
          "常态：湘妃竹杆狼毫笔",
          "战态：墨涛凝刃破虚空",
          "器灵真言：'形易得，神难求'"
        ],
        "origin_story": "璇玑子蘸银河星砂所制"
      },
      "key_items": [
        {
          "name": "无相册",
          "hidden_function": "吞噬恶人化作墨偶",
          "emotional_value": "存有璇玑子残影"
        }
      ]
    },
    "relationship_network": {
      "本源": {
        "name": "璇玑子",
        "influence": "画道极致如悬顶明月"
      },
      "羁绊": {
        "name": "卖茶盲妪",
        "bond_type": "忘年知音",
        "special_interaction": "惟盲妪能触其冰肌下墨血流动"
      }
    },
    "secrets_habits": {
      "hidden_acts": [
        "深夜对江铺十里画卷",
        "偷绘名门闺秀藏于瓦当"
      ],
      "vulnerabilities": "见撕画行为会灵力暴走"
    },
    "combat_profile": {
      "initiation": "蘸墨轻叹：'可惜了这幅皮囊'",
      "strengths": [
        "水墨领域内言出法随",
        "泼墨成兵无穷尽"
      ],
      "finishers": "掷笔成狱·画地为牢",
      "道体显兆": "鬓间墨痕蔓延如藤"
    },
    "红尘见闻": {
      "市井百态": [
        "为赌徒画亡妻像（暗中消其执念）",
