        "将泼皮无赖变作春宫图主角兜售"
      ],
      "困惑之事": [
        "书生为赝品画倾家荡产",
        "贵妇用金箔贴俗艳牡丹",
        "孩童撕名作折纸船"
      ]
    }
  }
