      {
        "name": "雪凰云翎",
        "bond_type": "闺中密友",
        "special_interaction": "为她编织冰晶冠冕"
      }
    ]
  },
  "secrets_habits": {
    "hidden_acts": [
      "偷戴探险队皮帽对冰镜傻笑",
      "舔冰柱被粘住舌头",
      "给冰雕企鹅开朝会"
    ],
    "private_collections": [
      "褪下的乳龙牙（刻幻想故事）"
    ],
    "vulnerabilities": [
      "遇暖流法力衰减",
      "见火焰误认是怪物"
    ]
  },
  "combat_profile": {
    "initiation": "举玉杖后退：莫...莫过来！（杖尖结冰花）",
