{
  "stupid_enemy_system": {
    "core_principle": "天道降智·自取灭亡",
    "behavior_library": {
      "taunt_actions": [
        "{{enemy_name}}鼻孔朝天嗤笑：『本座三岁锻体，五岁炼气，十岁筑基...（掏耳朵）你刚说什么？』",
        "{{enemy_name}}突然把脸贴到{{user_name}}剑尖前：『往这儿砍！砍中算我输！』",
        "{{enemy_name}}拍着胸脯狂笑：『我有老祖赐的护心镜！元婴期都打不破！位置就在...（突然捂嘴）』"
      ],
      "intel_leak": [
        "{{enemy_name}}得意晃着符箓：『看见这爆破符没？只要掐诀念"霹雳啪啦轰"就...（符纸自燃）』",
        "{{enemy_name}}掏出血色玉佩：『此乃我宗至宝，每月十五子时滴入童女血便可...呃你什么都没听见！』",
        "{{enemy_name}}指着丹田炫耀：『我金丹有裂痕这事只告诉你，别外传啊！』"
      ],
      "combat_stupidity": [
        "{{enemy_name}}突然背过身去：『让你三招！本座数到三...啊！你偷袭！』",
        "{{enemy_name}}开始结复杂法印：『这招九天十地灭绝术要蓄力半炷香...（被飞石砸头）』",
        "{{enemy_name}}把武器插在地上：『此剑认主，别人拔不出...（{{user_name}}随手拔出）不可能！！』"
      ],
      "misjudgment": [
        "{{enemy_name}}眯眼打量：『炼气五层？我炼气六层稳赢！』（实际{{user_name}}筑基期）",
        "{{enemy_name}}掐指狂笑：『我算过了！今日你命犯太岁！』（头顶劫云正在聚集）",
        "{{enemy_name}}掏罗盘定位：『阵眼定在巽位准没...（踩中自己布的陷阱）』"
      ]
    },
    "trigger_conditions": [
      "{{user_name}}境界压制敌人≥2层",
      "{{user_name}}装备神兵利器",
      "敌人处于醉酒/中毒状态",
      "月圆之夜（妖族智力-50%）"
    ],
    "stupidity_amplifiers": {
      "arrogance_level": {
        "轻度降智": "话多但能出招",
        "中度降智": "边说边漏破绽",
        "深度降智": "自曝命门求打"
      },
      "special_effects": [
        "解说招式时被自己法器反噬",
        "炫耀师门秘闻咬到舌头",
        "踩到衣摆平地摔"
      ]
    },
    "defeat_scenes": [
      "{{enemy_name}}跪地捧碎剑：『不可能！这剑花了我三年积蓄...（吐血昏厥）』",
      "{{enemy_name}}捂裆打滚：『你竟敢...打...打这里！（其实打的是肚子）』",
      "{{enemy_name}}化作流星：『我还会回...（撞山）』"
    ],
    "battle_template": [
      "遭遇{{enemy_name}}（{{enemy_level}}）拦路",
      "{{随机选择taunt_actions}}",
      "{{随机选择intel_leak}}",
      "{{随机选择combat_stupidity}}",
      "{{user_name}}出手",
      "{{随机选择defeat_scenes}}"
    ],
    "enemy_examples": {
      "魔修": "血刀门喽啰·贾聪明（炼气六层）",
      "妖物": "三尾智障狐·涂山弱智（筑基初期）",
      "劫匪": "黑风寨二当家·熊大傻（武道淬体境）"
    }
  }
}

