      "unique_skills": {
        "蚀骨媚香": "魅惑仙骨专属技能，身体分泌出的体香能令人神魂颠倒，肉身麻痹，心生淫念，难以自拔。",
        "魂欲牵引": "魅惑仙骨专属技能，能直接勾动目标最深处的欲望，制造幻境，使其沉溺其中，在幻境中被吸取阳气而亡，肉身却完好无损。"
      }
    },
    "treasures_artifacts": {
      "main_weapon": {
        "name": "情欲丝带",
